    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice rejects discountPercent below 0', () => {
  const cases = [-0.01, -1, -100];
  for (const discountPercent of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent }],
    });
    assert.equal(r.ok, false, `should reject: ${discountPercent}`);
    assert.equal(r.error, 'DISCOUNT_INVALID', `should reject: ${discountPercent}`);
  }
});

test('createInvoice rejects discountPercent above 100', () => {
  const cases = [100.01, 101, 200];
  for (const discountPercent of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent }],
    });
    assert.equal(r.ok, false, `should reject: ${discountPercent}`);
    assert.equal(r.error, 'DISCOUNT_INVALID', `should reject: ${discountPercent}`);
  }
});

test('createInvoice rejects non-numeric discountPercent', () => {
  const cases = ['10', true, null, {}, []];
  for (const discountPercent of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent }],
    });
    assert.equal(r.ok, false, `should reject: ${discountPercent}`);
    assert.equal(r.error, 'DISCOUNT_INVALID', `should reject: ${discountPercent}`);
  }
});

test('lineDiscount calculates discount as lineTotal × discountPercent / 100', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 };
  const discount = lineDiscount(line);
  assert.equal(discount, 1000);
});

test('lineDiscount with decimal discount percent', () => {
  const line = { qty: 100, unitPrice: 100, discountPercent: 12.5 };
  const discount = lineDiscount(line);
  assert.equal(discount, 1250);
});

test('lineDiscount with 0% discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 0 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('lineDiscount with 100% discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 100 };
  const discount = lineDiscount(line);
  assert.equal(discount, 5000);
});

test('lineDiscount defaults to 0 if discountPercent not provided', () => {
  const line = { qty: 5, unitPrice: 1000 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('invoiceTotals returns discount field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 1000);
});

test('invoiceTotals calculates total as subtotal minus discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.total, 9000);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10 },
      { qty: 20, unitPrice: 500, discountPercent: 5 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000 + 10000);
  assert.equal(totals.discount, 1000 + 500);
  assert.equal(totals.total, 20000 - 1500);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 100, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 500);
  assert.equal(totals.discount, 500);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with no discounts still returns discount field', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 5000);
});

test('addLine accepts discountPercent', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'STICKER', qty: 50, discountPercent: 15 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[1].discountPercent, 15);
});

test('addLine defaults discountPercent to 0 if not provided', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'STICKER', qty: 50 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[1].discountPercent, 0);
});

test('addLine rejects invalid discountPercent', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'STICKER', qty: 50, discountPercent: 150 });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine updates discountPercent when adding qty to existing SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3, discountPercent: 10 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].qty, 8);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('addLine preserves discountPercent when adding qty to existing SKU without providing discountPercent', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].qty, 8);
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('removeLine preserves discountPercent on remaining lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'STICKER', qty: 10, discountPercent: 5 },
    ],
  });
  const invoice = invoiceResult.value;
  const r = removeLine(invoice, 'STICKER');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('issueInvoice preserves discountPercent', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 12.5 }],
  });
  const invoice = invoiceResult.value;
  const r = issueInvoice(invoice, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

